function button(text,action,cls='primary',disabled=false){return `<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${esc(text)}</button>`}
function visual(id,caption=''){return `<div class="visual"><div class="product">${image(id)}${image(id,'reflection')}</div>${caption?`<span class="caption">${esc(caption)}</span>`:''}</div>`}
const shownPhotos=new Set();function image(id,cls=''){if(Core.get().credits&&!Core.get().credits[id])return '';shownPhotos.add(id);return `<img src="${DATA_BASE}photos/${esc(id)}.png" class="${cls}" alt="" decoding="async" onerror="this.hidden=true">`}
let autoT=null;function auto(action,ms=1700){clearTimeout(autoT);const bar=app.querySelector('.auto-bar');if(bar){bar.classList.remove('run');void bar.offsetWidth;bar.style.setProperty('--d',ms+'ms');bar.classList.add('run')}const page=pageName;autoT=setTimeout(()=>{if(pageName!==page)return;const b=app.querySelector(`[data-action="${action}"]`);if(b&&!b.disabled)b.click();else if(routes[action])go(action)},ms)}
function autoBar(){return '<div class="auto-bar" aria-hidden="true"><i></i></div>'}
function etapes(){return (s._cases&&s._cases.allergie)?6:5}
function dots(step,n=4){return `<div class="progress" aria-label="Étape ${step} sur ${n}">${Array.from({length:n},(_,i)=>`<i class="${i===step-1?'on':''}" aria-hidden="true"></i>`).join('')}<span>${step} / ${n}</span></div>`}
function bindCore(){Core.state(mode==='normal'?s:null,mode||'normal',prefs,removed,ry)}
function validBase(){return s.rien||!!(s._cases.allergie||s.grossesse||s.anticoagulant||s.reins||(s._cases.regime&&s.regime))}
function validQuestion(){if(s._cases.regime&&!s.regime)return false;return validBase()}
function syncScores(sc,isDemo=false){scores=sc;demo=isDemo;window.__vyScores=sc;bindCore()}
function go(name,replace=false){cleanup();cleanup=()=>{};pageName=name;history[replace?'replaceState':'pushState']({page:name},'',routes[name]);render();window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('popstate',()=>{cleanup();pageName=Object.entries(routes).find(([,v])=>location.pathname.endsWith(v))?.[0]||'questions';render()});
function shortDisclaimer(){return `<div class="notice">${esc(TEXT.info)}</div>`}
function globalChrome(){document.getElementById('brand').textContent=TEXT.brand;document.getElementById('navFood').textContent=TEXT.food;document.getElementById('navGallery').textContent=TEXT.gallery;document.getElementById('creditButton').textContent=TEXT.credits;document.getElementById('footerLabel').textContent=TEXT.food}
function computeRemaining(){const prevMode=mode;Core.state(s,'normal',prefs,removed,ry);const ex=Core.exclusions().x,n=Core.get().data.filter(f=>!ex[f.id]).length;bindCore();return n}
function review(){return `<div class="dictation">${esc(Core.phrase(validBase()?s:null))}</div><div class="overline">${computeRemaining()} aliments possibles</div>`}
function questions(){const notices=[s.grossesse?TEXT.pregnancy:'',s.anticoagulant?TEXT.anticoagulant:'',s.reins?TEXT.kidney:'',s.regime==='vegan'?TEXT.vegan:''].filter(Boolean);app.innerHTML=`<main class="solo"><section class="question-copy"><div class="overline">${TEXT.beforePlate}</div><h1>${esc(TEXT.avoid)}</h1><p>${esc(TEXT.avoidLead)}</p><div class="choices">${TEXT.cases.map(([id,t,sub])=>`<button class="choice ${!s.rien&&(s._cases[id]||s[id])?'selected':''}" data-case="${id}" aria-pressed="${!!(!s.rien&&(s._cases[id]||s[id]))}">${esc(t)}${sub?`<small>${esc(sub)}</small>`:''}</button>`).join('')}</div>${s._cases.regime?`<div class="choices">${[['vegetarien','Végétarien'],['vegan','Végan']].map(([id,t])=>`<button class="choice ${s.regime===id?'selected':''}" data-regime="${id}" aria-pressed="${s.regime===id}">${t}</button>`).join('')}</div>`:''}<button class="nothing ${s.rien?'selected':''}" data-action="nothing"><strong>${TEXT.nothing}</strong><small>${TEXT.nothingNote}</small></button>${notices.map(t=>`<div class="help">${esc(t)}</div>`).join('')}${s._cases.regime&&!s.regime?`<p class="help">${TEXT.regimeHelp}</p>`:''}${review()}${autoBar()}<div class="links">${button(TEXT.next,'questionNext','text-button',!validQuestion())}</div>${dots(1,etapes())}</section>${visual('grenade')}</main>`}
function allergies(){const c=Core.get();let options=Core.allergens.map(([id,t])=>[id,id==='autre'?TEXT.other:t]);app.innerHTML=`<main class="allergy-layout"><section><div class="overline">${TEXT.yourAllergies}</div><h1>${esc(TEXT.allergTitle)}</h1><p>${esc(TEXT.allergLead)}</p>${visual('kiwi')}</section><section><div class="choices">${options.map(([id,t])=>`<button class="choice ${(id==='autre'?s._autre:s.allergies.includes(id))?'selected':''}" data-allergen="${id}" aria-pressed="${!!(id==='autre'?s._autre:s.allergies.includes(id))}">${esc(t)}</button>`).join('')}</div>${s._autre?`<h3>${TEXT.otherTitle}</h3><p class="fine">${TEXT.otherHelp}</p><div class="choices other-list">${c.data.filter(f=>!(f.allergenes_UE||[]).length&&!['pamplemousse','huitre','tofu','noix_bresil'].includes(f.id)).map(f=>`<button class="choice ${s.autres_aliments.includes(f.id)?'selected':''}" data-other="${f.id}" aria-pressed="${s.autres_aliments.includes(f.id)}">${esc(f.nom.split(' (')[0])}</button>`).join('')}</div>`:''}<p class="help">${s.allergies.length||s.autres_aliments.length?TEXT.allergChange:TEXT.allergHint}</p>${review()}<div class="frame-actions">${button(TEXT.back,'questions','secondary')}${button(TEXT.next,'allergyNext','primary',!(s.allergies.length||s.autres_aliments.length)||(s._autre&&!s.autres_aliments.length))}</div>${dots(2)}</section></main>`}
function besoin(){const b=prefs.besoins||[];app.innerHTML=`<main class="solo preference"><section class="question-copy"><div class="overline">${TEXT.optional}</div><h1>${esc(TEXT.besoinTitle)}</h1><p>${TEXT.besoinLead}</p><div class="choices">${TEXT.besoins.map(([id,t])=>`<button class="choice ${b.includes(id)?'selected':''}" data-besoin="${id}" aria-pressed="${b.includes(id)}">${t}</button>`).join('')}</div><button class="nothing" data-action="besoinAny"><strong>${TEXT.besoinAny}</strong></button>${autoBar()}<div class="links">${button(TEXT.back,s._cases.allergie?'allergies':'questions','text-button')}${button(TEXT.next,'types','text-button')}</div>${dots(s._cases.allergie?3:2,etapes())}</section>${visual('citron')}</main>`}
function envies(){const t=prefs.types||[];app.innerHTML=`<main class="solo preference"><section class="question-copy"><div class="overline">${TEXT.optional}</div><h1>${esc(TEXT.typesTitle)}</h1><p>${TEXT.typesLead}</p><div class="choices">${TEXT.types.map(([id,x])=>`<button class="choice ${t.includes(id)?'selected':''}" data-type="${id}" aria-pressed="${t.includes(id)}">${x}</button>`).join('')}</div><button class="nothing" data-action="typesAny"><strong>${TEXT.typesAny}</strong></button>${autoBar()}<div class="links">${button(TEXT.back,'besoin','text-button')}${button(TEXT.next,'preference','text-button')}</div>${dots(s._cases.allergie?4:3,etapes())}</section>${visual(t.includes('epices')?'curcuma':t.includes('boissons')?'the_vert':t.includes('legumes')?'brocoli':'fraise')}</main>`}
function preference(){app.innerHTML=`<main class="solo preference"><section class="question-copy"><div class="overline">${TEXT.optional}</div><h1>${esc(TEXT.preference)}</h1><p>${TEXT.preferenceLead}</p><div class="choices">${TEXT.usage.map(([id,t])=>`<button class="choice ${(prefs.usage||'')===id?'selected':''}" data-usage="${id}" aria-pressed="${(prefs.usage||'')===id}">${t}</button>`).join('')}<button class="choice ${prefs.bio?'selected':''}" data-bio="1" aria-pressed="${!!prefs.bio}">${TEXT.bioLabel}</button></div>${autoBar()}<div class="links">${button(TEXT.back,'types','text-button')}${button(TEXT.next,'consent','text-button')}</div>${dots(etapes()-1,etapes())}</section>${visual(prefs.usage==='tendance'?'avocat':prefs.usage==='decouverte'?'fruit_passion':'orange')}</main>`}
function agreement(){const ageKnown=window.vyPrefs?.get&&['25','35','45','55'].includes(String(window.vyPrefs.get().age));app.innerHTML=`<main class="solo consent-view"><section class="question-copy"><div class="overline">${TEXT.beforeReading}</div><h1>${esc(TEXT.consentTitle)}</h1>${review()}<p class="consent">${esc((ageKnown?'':TEXT.age)+TEXT.consent)}</p>${button(TEXT.accept,'accept','primary',!Core.valid(s))}<div class="links">${button(TEXT.minor,'minor','text-button')}${button(TEXT.refuse,'refuse','text-button')}</div><p class="fine">${TEXT.warningShort}</p><details><summary>${TEXT.warningLink}</summary><p>${esc(TEXT.warningFull)}</p></details><div class="links">${button(TEXT.back,'preference','text-button')}</div>${dots(s._cases.allergie?4:3,s._cases.allergie?4:3)}</section>${visual('poire')}</main>`}
function loadMemory(){try{const m=JSON.parse(localStorage.getItem(MEMORY)||'null');if(!m)return null;const z=m.sante||{},allergyCodes=Core.allergens.map(x=>x[0]).filter(x=>x!=='autre');const valid=m.schema===2&&m.accord?.texte===ACCORD&&m.majeur===true&&Number.isFinite(Date.parse(m.expire))&&new Date(m.expire)>=new Date()&&typeof z.rien==='boolean'&&Array.isArray(z.allergies)&&z.allergies.every(x=>allergyCodes.includes(x))&&Array.isArray(z.autres_aliments)&&z.autres_aliments.every(x=>Core.get().data.some(f=>f.id===x))&&[null,'vegetarien','vegan'].includes(z.regime??null)&&!(z.rien&&(z.allergies.length||z.autres_aliments.length||z.grossesse||z.anticoagulant||z.reins||z.regime))&&(z.rien||z.allergies.length||z.autres_aliments.length||z.grossesse||z.anticoagulant||z.reins||z.regime);if(!valid){localStorage.removeItem(MEMORY);localStorage.removeItem(PREFS);return null}return m}catch{localStorage.removeItem(MEMORY);localStorage.removeItem(PREFS);return null}}
function returnView(){if(!saved){app.innerHTML=`<main class="solo"><section><h1>${esc(TEXT.returnTitle)}</h1><p>${TEXT.noSaved}</p>${button(TEXT.start,'questions')}</section>${visual('poire')}</main>`;return}app.innerHTML=`<main class="solo"><section><div class="overline">${TEXT.answersFrom} ${esc(new Date(saved.le+'T12:00:00').toLocaleDateString('fr-FR'))}</div><h1>${esc(TEXT.returnTitle)}</h1><p class="dictation">${esc(Core.phrase(saved.sante))}</p><div class="frame-actions">${button(TEXT.returnYes,'same')}${button(TEXT.changed,'modify','secondary')}</div><div class="links">${button(TEXT.another,'another','text-button')}${button(TEXT.erase,'eraseReturn','text-button')}</div></section>${visual('poire')}</main>`}
function cleanHealth(){let z=JSON.parse(JSON.stringify(s));delete z._cases;delete z._autre;z.rien=!!z.rien;return z}
function saveMemory(renew=false){if(!keep||mode!=='normal')return;const now=new Date(),end=new Date();end.setMonth(end.getMonth()+6);let expire=renew||!saved?end.toISOString().slice(0,10):saved.expire;let record={schema:2,accord:{texte:ACCORD,le:renew?now.toISOString():(saved?.accord?.le||now.toISOString())},majeur:true,le:now.toISOString().slice(0,10),expire,sante:cleanHealth(),rythme:ry,paspour:removed};localStorage.setItem(MEMORY,JSON.stringify(record));localStorage.setItem(PREFS,JSON.stringify(prefs));saved=record}
function eraseMemory(returnToQuestion=false){const previous={m:localStorage.getItem(MEMORY),p:localStorage.getItem(PREFS),s:JSON.parse(JSON.stringify(s)),saved,mode,prefs:JSON.parse(JSON.stringify(prefs)),removed:[...removed],ry:JSON.parse(JSON.stringify(ry)),keep};localStorage.removeItem(MEMORY);localStorage.removeItem(PREFS);keep=false;s={_cases:{},allergies:[],autres_aliments:[]};saved=null;mode=null;removed=[];ry={q9s:null,q9d:false,q10p:null};if(returnToQuestion)go('questions');else{mode='prudent';render()}const toast=document.createElement('div');toast.className='toast';toast.innerHTML=`${TEXT.erased}${button(TEXT.undo,'undo','text-button')}`;document.body.append(toast);toast.querySelector('button').onclick=()=>{if(previous.m)localStorage.setItem(MEMORY,previous.m);if(previous.p)localStorage.setItem(PREFS,previous.p);s=previous.s;saved=previous.saved;mode=previous.mode;prefs=previous.prefs;removed=previous.removed;ry=previous.ry;keep=previous.keep;toast.remove();render()};setTimeout(()=>toast.remove(),5000)}
let modelPromise=null;
async function models(){if(modelPromise)return modelPromise;modelPromise=(async()=>{if(!window.faceapi){await script('/scan/vendor/face-api-1.7.15.min.js')}if(!window.VYVRE_SCAN_ENGINE)await script('/scan/vyvre-scan-engine.js?v=10.6');await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri('/scan/models/faceapi'),faceapi.nets.faceLandmark68Net.loadFromUri('/scan/models/faceapi')]);return window.VYVRE_SCAN_ENGINE})();try{return await modelPromise}catch(e){modelPromise=null;throw e}}
function script(src){return new Promise((resolve,reject)=>{let tag=document.createElement('script');tag.src=src;tag.onload=resolve;tag.onerror=reject;document.head.append(tag)})}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function scanView(){app.innerHTML=`<main class="scan-layout${!scores?' en-lecture':''}"><div class="camera idle">${demo?'<img id="scanImage" src="portrait-demo.jpg" alt="Photo de démonstration">': '<video id="video" autoplay muted playsinline></video>'}<div class="oval"></div><div class="scanline"></div><div class="camera-label">${esc(demo?TEXT.demoLabel:TEXT.privacyImage)}</div></div><section class="scan-copy"><div class="overline">Lecture de peau</div><h1>${esc(TEXT.scanTitle)}</h1><p>${TEXT.scanLead}</p><div class="live-status" aria-live="polite"><div class="phase" id="scanPhase">${scores?TEXT.done:TEXT.ready}</div><div id="scanConditions" class="help"></div></div>${scores?'':'<div id="vyRecherche" class="recherche"></div>'}<div id="vyLive" class="live-panel"></div><div id="scanMeters"></div><div id="scanContinue">${scores?button(TEXT.goComposition,'composition'):''}</div><div class="frame-actions${stream&&!scores?' en-direct':''}">${button(TEXT.camera,'camera',scores?'secondary':'primary')}${!scores?button(TEXT.read,'read','secondary',!stream):''}<label class="secondary" tabindex="0">${TEXT.upload}<input id="upload" type="file" accept="image/*"></label></div><div class="links">${hasStoredScan()?button(TEXT.lastScan,'lastScan','text-button'):''}</div><div id="scanError" class="error" role="alert"></div>${demo?`<p class="fine">${TEXT.demoNote}</p>`:''}${dots(2,5)}</section></main>`;if(stream){let v=document.getElementById('video');v.srcObject=stream;v.play().catch(()=>{})}if(scores)showMeters(scores);document.getElementById('upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;/* une photo choisie pendant la lecture automatique : on coupe la camera, puis on lit la photo */if(scanBusy||stream){stopCamera();for(let i=0;i<60&&scanBusy;i++)await new Promise(r=>setTimeout(r,100))}const url=URL.createObjectURL(f);runImage(url,false).finally(()=>URL.revokeObjectURL(url))};const label=app.querySelector('label');label.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();document.getElementById('upload').click()}};cleanup=()=>{clearTimeout(autoT);clearInterval(rechercheT);stopCamera()};
 if(!scores)recherche();
 /* 30/09 (Charles) : en arrivant, la camera s'ouvre et la lecture demarre seules ; une fois lue, on passe a la composition */
 if(!scores&&!stream&&!scanBusy&&!autoCam){autoCam=true;camera()}
 else if(scores&&!demo){const page=pageName;clearTimeout(autoT);autoT=setTimeout(()=>{if(pageName===page)go('composition')},1800)}}
let autoCam=false;
function showMeters(sc){const selected=[['glow','Éclat'],['redness','Rougeurs'],['hydration','Hydratation'],['pores','Pores']].filter(([k])=>typeof sc[k]==='number'&&Number.isFinite(sc[k]));const box=document.getElementById('scanMeters');if(box)box.innerHTML=`<div class="meters">${selected.map(([k,t])=>`<div class="meter"><span>${t}</span><div class="track"><b style="width:${Math.max(0,Math.min(100,sc[k]))}%"></b></div><span>${Math.round(sc[k])}/100</span></div>`).join('')}</div>`}
function hasStoredScan(){try{const z=JSON.parse(localStorage.getItem('vyvre_scan_scores'));return z&&Object.entries(z).some(([k,v])=>['glow','redness','hydration','pores','sebum','pigmentation','wrinkles','firmness'].includes(k)&&typeof v==='number'&&Number.isFinite(v))?z:null}catch{return null}}
function phase(t){const el=document.getElementById('scanPhase');if(el)el.textContent=t}
async function camera(){if(scanBusy)return;try{stopCamera();demo=false;scores=null;window.__vyScores=null;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280},height:{ideal:960}},audio:false});scanView();phase(TEXT.ready);models().catch(()=>{});const v=document.getElementById('video');const lancer=()=>setTimeout(()=>{if(pageName==='scan'&&stream&&!scanBusy&&!scores)readVideo()},700);if(v&&v.readyState>=2)lancer();else v&&v.addEventListener('playing',lancer,{once:true})}catch(e){document.getElementById('scanError').textContent=TEXT.cameraError}}
async function readVideo(){if(!stream||scanBusy)return;scanBusy=true;app.querySelector('.camera').classList.remove('idle');app.querySelectorAll('button').forEach(b=>b.disabled=true);try{phase(TEXT.loadingModels);const eng=await models();const result=await eng.runRealScanWithFeedback(document.getElementById('video'),event=>{if(event.phase==='positioning'){phase(TEXT.positioning);const z=document.getElementById('scanConditions');z.textContent=[event.light==='OK'?TEXT.lightOK:event.light==='too_dark'?TEXT.lightDark:event.light==='too_bright'?TEXT.lightBright:'',event.distance==='OK'?TEXT.frameOK:event.distance==='too_far'?TEXT.nearer:event.distance==='too_close'?TEXT.further:event.distance==='no_face'?TEXT.faceInFrame:'',event.stability==='unsteady'?TEXT.stillHead:''].filter(Boolean).join(' · ')}else if(event.phase==='capturing')phase(TEXT.capturing+(event.countdown?' '+event.countdown:''));else if(event.phase==='analyzing')phase(TEXT.analyzing);else if(event.phase==='done'){phase(TEXT.done);showMeters(event.scores)}});if(!result?.scores||result.rejected){const e2=Error('rejected');e2.issues=result&&result.issues;throw e2}syncScores(result.scores,false);essais=0;stopCamera();scanView()}catch(e){/* 30/09 : la raison s'affiche dans la page (la fenetre sombre du moteur est cachee), puis nouvelle tentative seule, deux fois au plus */const RAISONS={NO_FACE:'Aucun visage : placez-vous face à la caméra.',MULTIPLE_FACES:'Un seul visage dans le cadre.',FACE_TOO_SMALL:'Trop loin : rapprochez-vous à environ 30 cm.',FACE_TOO_LARGE:'Trop près : reculez légèrement.',OFF_CENTER:'Centrez votre visage dans le cadre.',LOW_LUMINANCE:'Pas assez de lumière : placez-vous face à une fenêtre.',HIGH_LUMINANCE:'Trop de lumière : évitez le contre-jour.',LOW_VARIANCE:'Image floue : tenez l’appareil immobile.',OCCLUDED_LANDMARKS:'Visage masqué : dégagez les yeux, le nez et la bouche.',WRONG_ANGLE:'Regardez droit vers la caméra, le visage de face.',INSUFFICIENT_FRAMES:'Restez immobile quelques secondes.'};const txt=(e.issues||[]).map(i=>RAISONS[i.code]||'').filter(Boolean).join(' ')||TEXT.scanError;const fa=app.querySelector('.frame-actions');if(fa)fa.classList.remove('en-direct');app.querySelectorAll('button').forEach(b=>b.disabled=false);app.querySelector('.camera')?.classList.add('idle');if(stream&&essais<2&&pageName==='scan'){essais++;phase(txt+' Nouvelle tentative dans un instant…');document.getElementById('scanError').textContent='';const page=pageName;setTimeout(()=>{if(pageName===page&&stream&&!scores&&!scanBusy){app.querySelector('.frame-actions')?.classList.add('en-direct');readVideo()}},3500)}else{phase(txt);document.getElementById('scanError').textContent=txt}}finally{scanBusy=false}}
/* 30/09 (Charles : « a droite, pendant le scan, que ca cherche les fruits et legumes en meme temps ») :
   pendant la lecture, une roue de vraies photos defile parmi les aliments AUTORISES pour cette personne (exclusions appliquees).
   La piste suit ses besoins, puis ce que la camera mesure a l'instant (rougeur a*, clarte L*). Le choix final se fait a la fin. */
let rechercheT=null;
function recherche(){clearInterval(rechercheT);const zone=document.getElementById('vyRecherche');if(!zone)return;bindCore();
 const c=Core.get(),ex=Core.exclusions(),ok=c.data.filter(f=>!ex.x[f.id]&&['A','B','C'].includes(f.niveau_preuve_peau)&&c.credits[f.id]);if(!ok.length)return;
 const lab=k=>(Core.labels[k]||k).toLowerCase();let i=0,roule=[];
 const piste=()=>{const b=prefs.besoins||[];if(b.length)return b[Math.floor(Date.now()/3000)%b.length];const m=window.__vyMES;if(m&&m.zones){const j=m.zones.Joues||m.zones.Front;if(j&&j.a>17)return 'rougeurs';if(j&&j.L<55)return 'eclat';if(m.lumiere>70)return 'uniformite'}return ['eclat','rougeurs','rides_fermete','pores_sebum'][Math.floor(Date.now()/3000)%4]};
 const tour=()=>{if(!document.body.contains(zone)){clearInterval(rechercheT);return}const k=piste(),pool=ok.filter(f=>f.cibles_peau.includes(k));const src=pool.length>=5?pool:ok;
  if(!roule.length||roule.k!==k){roule=src.slice().sort(()=>Math.random()-.5);roule.k=k}i++;
  const it=n=>roule[(i+n+roule.length*9)%roule.length];
  zone.innerHTML=`<div class="overline">Recherche en direct</div><div class="roue-live">${[-2,-1,0,1,2].map(n=>{const f=it(n);return `<div class="rl ${n===0?'on':''}" style="--n:${n}">${image(f.id)}<span>${esc(f.nom.split(' (')[0])}</span>${n===0?`<em>${esc(lab(f.cibles_peau.includes(k)?k:f.cibles_peau[0]))}</em>`:''}</div>`}).join('')}</div><div class="compte"><span><b>${c.data.length}</b> étudiés</span><span><b>${Object.keys(ex.x).filter(id=>c.data.some(f=>f.id===id)).length}</b> écartés pour vous</span><span><b>${pool.length}</b> pour ${esc(lab(k))}</span></div><p class="fine">Piste en direct : ${esc(lab(k))}. Votre assiette sera composée à la fin de la lecture.</p>`};
 tour();rechercheT=setInterval(tour,650)}

let essais=0;
async function runImage(url,isDemo){if(scanBusy)return;scanBusy=true;stopCamera();demo=isDemo;scanView();phase(TEXT.loadingModels);app.querySelectorAll('button').forEach(b=>b.disabled=true);const cameraBox=app.querySelector('.camera');cameraBox.classList.remove('idle');let img=document.createElement('img');img.id='scanImage';img.alt=isDemo?TEXT.demoLabel:TEXT.yourPhoto;img.src=url;cameraBox.prepend(img);try{await img.decode();const eng=await models();phase(TEXT.positioning);const detection=await faceapi.detectSingleFace(img,new faceapi.TinyFaceDetectorOptions({inputSize:416,scoreThreshold:.4})).withFaceLandmarks();if(!detection)throw Error('no face');phase(TEXT.analyzing);const result=await scanFromImage(img);if(!result?.scores)throw Error('no scores');syncScores(result.scores,isDemo);scanView();if(!isDemo){const display=app.querySelector('.camera');display.querySelector('video')?.remove();let copy=img.cloneNode();copy.removeAttribute('id');display.prepend(copy)}return result}catch(e){phase(TEXT.scanError);document.getElementById('scanError').textContent=TEXT.scanError;app.querySelectorAll('button').forEach(b=>b.disabled=false);throw e}finally{scanBusy=false}}
async function demoForDestination(destination){go('scan');await runImage('portrait-demo.jpg',true);if(destination)go(destination)}
function missingScan(){app.innerHTML=`<main class="solo"><section><div class="overline">${TEXT.yourJourney}</div><h1>${esc(TEXT.scanNone)}</h1><p>${TEXT.noScanLead}</p>${button(TEXT.camera,'scan')}<div class="links"></div></section>${visual('avocat')}</main>`}
function prepareSelection(){if(!mode)mode='prudent';bindCore();const ind=Core.indices();if(!ind)return null;const chosen=Core.choose(ind),ex=Core.exclusions();const c=Core.get();const allowed=c.data.filter(f=>!ex.x[f.id]);const relevant=allowed.filter(f=>['A','B','C'].includes(f.niveau_preuve_peau)&&[ind.i1,ind.i2,...(ind.suite||[])].some(k=>f.cibles_peau.includes(k)));const excluded=c.data.length-allowed.length;return{ind,chosen,ex,data:c.data,allowed,relevant,excluded}}
function composition(wheel=false){const selection=prepareSelection();if(!selection){missingScan();return}const {data,chosen,excluded,relevant}=selection;const sample=data.filter(f=>Core.get().credits[f.id]&&['grenade','orange','citron','kiwi','avocat','mangue','fraise','poire','peche','chou_rouge','radis','clementine'].includes(f.id));app.innerHTML=`<main class="composition"><div class="stage" aria-hidden="true"></div><section class="composition-copy"><div class="overline">${TEXT.compositionEyebrow}</div><h1 id="composeTitle">${TEXT.composeTitle}</h1><p id="composePhase" aria-live="polite">${TEXT.composeLead}</p>${wheel?'<div class="wheel" aria-hidden="true"><div class="wheel-track"></div></div>':''}<div class="landing">${chosen.map((c,i)=>`<div class="slot" data-slot="${i}">${image(c.f.id)}${image(c.f.id,'reflection')}<span>${esc(c.f.nom.split(' (')[0])}</span></div>`).join('')}</div><div id="composeTrace" class="trace"></div><div id="composeContinue">${button(TEXT.showPlate,'result','primary',true)}</div><div class="links" style="justify-content:center">${button(TEXT.pause,'pauseMotion','text-button')}${button(TEXT.showPlate,'result','text-button')}</div>${demo?`<p class="fine" style="margin-top:16px">${TEXT.demoLabel}</p>`:''}</section></main>`;
const stage=app.querySelector('.stage');const fruits=sample.map(f=>{const el=document.createElement('div');el.className='moving-fruit';el.innerHTML=image(f.id)+image(f.id,'reflection');stage.append(el);return el});const stageBounds=stage.getBoundingClientRect();const chosenSprites=chosen.map((c,i)=>{const el=document.createElement('div');el.className='moving-fruit chosen-fruit';el.innerHTML=image(c.f.id)+image(c.f.id,'reflection');el.style.transformOrigin='50% 0';el.style.zIndex=30;stage.append(el);const slot=app.querySelector(`[data-slot="${i}"]`);slot.style.transform="none";slot.style.transition="opacity .2s ease";const target=slot.getBoundingClientRect();return{el,x:target.left+target.width/2-stageBounds.left-stageBounds.width/2,y:target.top-stageBounds.top}});const reduced=matchMedia('(prefers-reduced-motion: reduce)');let stopped=reduced.matches,paused=false,t0=performance.now(),last=t0,elapsed=0,raf;let track=app.querySelector('.wheel-track');const wheelFoods=relevant.filter(f=>Core.get().credits[f.id]);if(track)track.innerHTML=Array.from({length:4},()=>wheelFoods.map(f=>`<div class="wheel-row">${image(f.id)}${esc(f.nom.split(' (')[0])}</div>`).join('')).join('');
const messages=[`${data.length} ${TEXT.studied.toLowerCase()}.`,`${excluded} ${TEXT.excluded.toLowerCase()}.`,`${relevant.length} ${TEXT.ranked.toLowerCase()}.`,`${chosen.length} ${TEXT.retained.toLowerCase()}.`];
const motionButton=app.querySelector('[data-action="pauseMotion"]');motionButton.onclick=()=>{paused=!paused;motionButton.textContent=paused?TEXT.play:TEXT.pause;last=performance.now();if(!paused&&!raf)raf=requestAnimationFrame(frame)};
function frame(now){raf=null;elapsed+=Math.min(100,now-last);last=now;const seconds=elapsed/1000;const stageIndex=Math.min(3,Math.floor(seconds/1.35));if(stageIndex!==frame.lastPhase){bindCore();if(stageIndex===1){const actualEx=Core.exclusions().x;messages[1]=`${data.filter(f=>actualEx[f.id]).length} ${TEXT.excluded.toLowerCase()}.`}if(stageIndex===2){const actualEx=Core.exclusions().x;messages[2]=`${data.filter(f=>!actualEx[f.id]&&['A','B','C'].includes(f.niveau_preuve_peau)&&[selection.ind.i1,selection.ind.i2,...(selection.ind.suite||[])].some(k=>f.cibles_peau.includes(k))).length} ${TEXT.ranked.toLowerCase()}.`}if(stageIndex===3){const actualChoice=Core.choose(selection.ind);messages[3]=`${actualChoice.length} ${TEXT.retained.toLowerCase()}.`}frame.lastPhase=stageIndex;}document.getElementById('composePhase').textContent=messages[stageIndex];document.getElementById('composeTrace').textContent=messages.slice(0,stageIndex+1).join(' · ');const w=stage.clientWidth,h=stage.clientHeight,mobile=w<650;fruits.forEach((el,i)=>{const row=i%2,k=Math.floor(i/2),gap=mobile?180:250,count=Math.ceil(fruits.length/2),span=count*gap;let distance=seconds<4?seconds*65:260+110*(1-Math.exp(-(seconds-4)));let x=((k*gap-distance*(row?-1:1)+span*10)%span)-span/2;el.style.transform=`translate3d(calc(-50% + ${x}px),${row?h-(mobile?154:205):5}px,0) rotate(${row?-5:5}deg)`;el.style.opacity=seconds>2.6?Math.max(0,1-(seconds-2.6)/1.6):1});
if(track&&wheelFoods.length){const k=Math.min(chosen.length-1,Math.max(0,Math.floor((seconds-3.6)/1.2))),selected=chosen[k]?.f;let pos=wheelFoods.findIndex(f=>f.id===selected?.id);const local=Math.max(0,Math.min(1,(seconds-3.6-k*1.2)/1.2)),ease=1-Math.pow(1-local,4);let target=(wheelFoods.length+Math.max(0,pos))*50-80;track.style.transform=`translateY(${-target*ease}px)`}
chosenSprites.forEach((item,i)=>{const begin=3.1+i*.85,done=4.2+i*.85,u=Math.max(0,Math.min(1,(seconds-begin)/1.1)),ez=1-Math.pow(1-u,4),row=i%2,startX=(Math.floor(i/2)-.5)*Math.min(w*.48,530),startY=row?h-(mobile?154:205):5,scale=1-ez*(mobile?.4:.485);item.el.style.transform=`translate3d(calc(-50% + ${startX+(item.x-startX)*ez}px),${startY+(item.y-startY)*ez}px,0) scale(${scale})`;item.el.style.opacity=seconds<2.6||seconds>done||stopped?0:1;app.querySelector(`[data-slot="${i}"]`).classList.toggle('arrived',seconds>done||stopped)});const done=seconds>4.2+chosen.length*.85||stopped;if(done){document.getElementById('composePhase').textContent=messages[3];document.getElementById('composeContinue').querySelector('button').disabled=false;if(!composition.fini){composition.fini=1;const page=pageName;setTimeout(()=>{composition.fini=0;if(pageName===page&&!paused)go('result')},2600)}}if(!paused&&!stopped&&seconds<9)raf=requestAnimationFrame(frame)}
if(stopped){elapsed=10000;frame(performance.now())}else raf=requestAnimationFrame(frame);const visibility=()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=null}else if(!paused&&!stopped&&elapsed<9000){last=performance.now();raf=requestAnimationFrame(frame)}};document.addEventListener('visibilitychange',visibility);cleanup=()=>{cancelAnimationFrame(raf);document.removeEventListener('visibilitychange',visibility)};
}
function filterUI(){return `<div class="overline">${TEXT.refine}</div><div class="filterbar"><button class="choice ${prefs.saison?'selected':''}" data-filter="saison" aria-pressed="${prefs.saison}">${TEXT.inSeason}</button><select id="budget" aria-label="${TEXT.budget}">${TEXT.budgetOptions.map(([id,t])=>`<option value="${id}" ${prefs.budget===id||(!prefs.budget&&!id)?'selected':''}>${TEXT.budget} : ${t}</option>`).join('')}</select><button class="choice ${prefs.bio?'selected':''}" data-filter="bio" aria-pressed="${prefs.bio}">${TEXT.bio}</button><button class="choice ${prefs.cuis?'selected':''}" data-filter="cuis">${TEXT.cuisine}${prefs.cuisines.length?' · '+prefs.cuisines.length:''}</button>${removed.length?button(TEXT.reset+' ('+removed.length+')','resetRemoved','choice'):''}</div>${prefs.cuis?`<div class="filter-panel">${Core.cuisines.map(([id,t])=>`<button class="choice ${prefs.cuisines.includes(id)?'selected':''}" data-cuisine="${id}" aria-pressed="${prefs.cuisines.includes(id)}">${t}</button>`).join('')}</div>`:''}<p class="fine">${TEXT.filtersHint}</p>`}
/* 30/09 (Charles) : les mots qui comptent en gras, surlignes au defilement ; le lien avec la peau, explicite et legal */
const MOTS_FORTS=['vitamine C','vitamine A','vitamine E','vitamine K','bêta-carotène','provitamine A','lycopène','lutéine','anthocyanes','polyphénols','oméga-3','oméga 3','EPA','DHA','fibres','potassium','zinc','sélénium','cuivre','iode','riboflavine','niacine','folates','collagène','UV','peau','cuit','cuite','huile','crue','cru'];
const RE_FORTS=new RegExp('(\\d+(?:[,.]\\d+)?\\s?(?:%|mg|µg|g|ml)\\b|'+MOTS_FORTS.map(m=>m.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');
function fort(t){return esc(t).replace(RE_FORTS,'<b class="hl">$1</b>')}
function pourquoi(c){const ind=Core.indices()||{},k=c.pour,lab=(Core.labels[k]||TEXT.thisAspect).toLowerCase(),demande=(prefs.besoins||[]).includes(k),note=k===ind.i1?ind.n1:k===ind.i2?ind.n2:null;return `<p class="pourquoi"><b class="hl">Pour votre ${esc(lab)}</b> · ${demande?'vous l’avez demandé':note!=null?'votre lecture : '+note+'/100':'un point de votre lecture'}${demande&&note!=null?' · lecture '+note+'/100':''}.</p>`}
function lien(f){const l=Core.skinLinks?Core.skinLinks(f):[];if(!l.length)return `<p class="fine">Pas d’allégation santé autorisée pour la peau sur cet aliment : il est choisi pour sa composition et pour les études ci-dessous.</p>`;return `<div class="lien-peau"><div class="overline">Le lien avec la peau · allégation autorisée (UE)</div>${l.map(x=>`<p><b class="hl">${x.niveau==='Source'?(/^[aeiouy]/i.test(x.nutriment)?'Source d’':'Source de '):'Riche en '}${esc(x.nutriment)}</b> · ${x.pct} % des apports de référence pour 100 g.<br><span class="allegation">${esc(x.allegation)}</span></p>`).join('')}<p class="fine">${TEXT.info}</p></div>`}
const surligne=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('vu');surligne.unobserve(e.target)}}),{rootMargin:'0px 0px -12% 0px'});
new MutationObserver(()=>document.querySelectorAll('b.hl:not(.suivi)').forEach(b=>{b.classList.add('suivi');surligne.observe(b)})).observe(document.documentElement,{childList:true,subtree:true});

function detailsFor(c,i,ex){const f=c.f,claim=Core.claim(f),precautions=[...(ex.notes[f.id]||[]),...(f.precautions||[]),...(f.reactions_croisees||[])];return `<article class="food-detail" id="food-${i}">${visual(f.id)}<div><div class="overline">${String(i+1).padStart(2,'0')} / ${esc(Core.labels[c.pour]||'Composition')}</div><h3>${esc(f.nom)}</h3><p class="accroche">${fort(f.accroche||'')}</p><div class="overline">${TEXT.why}</div>${pourquoi(c)}<p>${fort(Core.fact(f)||'')}</p>${lien(f)}<div class="portion-grid"><div><div class="overline">${TEXT.howMuch}</div><p>${esc(f.portion_type)}. ${esc(Core.frequency[f.categorie]||'Dans une alimentation variée.')}</p></div><div><div class="overline">${TEXT.portion}</div><p>${Core.contributions(f).map(fort).join('<br>')||TEXT.noFoodsKnown}</p></div></div>${claim&&!(Core.skinLinks(f)||[]).some(x=>x.allegation.replace(/[’'.]/g,'')===claim.replace(/[’'.]/g,''))&&!/peau/i.test(claim)?`<div class="alleg">${esc(claim)}</div>`:''}<div class="overline">${TEXT.evidence} · ${esc(f.niveau_preuve_peau)}</div><p>${esc(Core.evidence[f.niveau_preuve_peau]||'')}</p><div class="overline">${TEXT.precautions}</div>${(f.allergenes_UE||[]).length?`<p class="prec">${TEXT.allergens} : ${f.allergenes_UE.map(a=>esc(Core.allergenNames[a]||a)).join(', ')}.</p>`:''}${(f.allergenes_possibles||[]).length?`<p class="prec">${TEXT.byBrand} : ${f.allergenes_possibles.map(a=>esc(Core.allergenNames[a]||a)).join(', ')}.</p>`:''}${precautions.map(t=>`<p class="prec">${esc(t)}</p>`).join('')}${!(precautions.length||(f.allergenes_UE||[]).length)?'<p class="fine">'+TEXT.unknownPrecaution+'</p>':''}<details class="etudes" open><summary>${TEXT.studies} (${(f.etudes||[]).length})</summary><p>${fort(f.mecanisme_simple||'')} <span class="fine">${TEXT.science}</span></p>${(f.etudes||[]).map(e=>`<p><a href="${esc(e.lien)}" target="_blank" rel="noopener">${esc(e.ref)} ↗</a></p>`).join('')}</details><details ${f.accroche_nutrition_verifiee?'open':''}><summary>${TEXT.nutrition}</summary><table class="nutrition-table">${Object.entries(f.ciqual?.teneurs_pour_100g||{}).map(([k,v])=>`<tr><td>${esc(k.replace(/_/g,' '))}</td><td>${typeof v==='number'?esc(v.toLocaleString('fr-FR')):TEXT.notKnown}</td></tr>`).join('')}</table><p class="fine">${esc(f.ciqual?.source||'ANSES, table CIQUAL 2020')} · ${esc(f.ciqual?.nom_ciqual||'')}</p></details>${Core.credit(f.id)}${mode==='normal'?`<button class="text-button" data-remove="${esc(f.id)}">${TEXT.notForMe}</button>`:''}</div></article>`}
function resultView(solo=false){const z=prepareSelection();if(!z){missingScan();return}const {chosen,ind,ex,excluded,data}=z;const seasonal=chosen.filter(c=>(c.f.saison||[]).includes(new Date().getMonth()+1)).length;const proof=chosen.map(c=>c.f.niveau_preuve_peau).sort()[0]||'—';app.innerHTML=`<main class="results ${solo?'result-solo':''}"><div class="result-head"><div><div class="overline">${TEXT.editEyebrow}${demo?' · '+TEXT.photoDemo:''}</div><h1>${esc(mode==='normal'?TEXT.result:TEXT.prudent)}</h1></div><p>${esc(mode==='normal'?TEXT.resultLead:TEXT.prudentLead)}${demo?`<br><strong style="font-weight:400">${TEXT.demoLabel}</strong>`:''}</p></div>${!chosen.length?`<p>${TEXT.noFood}</p>`:`<div class="result-grid"><article class="paper"><div class="overline">${TEXT.reading} · ${esc(Core.labels[ind.i1])}${demo?' · '+TEXT.demonstration:''}</div><div class="hero-food">${visual(chosen[foodFocus%chosen.length].f.id)}${solo?`<div class="hero-name">${esc(chosen[foodFocus%chosen.length].f.nom.split(' (')[0])}</div>`:''}</div>${solo?`<div class="hero-tabs">${chosen.map((c,i)=>`<button class="${i===foodFocus?'on':''}" data-focus="${i}">${esc(c.f.nom.split(' (')[0])}</button>`).join('')}</div>`:''}<p class="fine">${excluded} ${TEXT.foodsExcludedAmong} ${data.length}. ${chosen.length?'':TEXT.notStudied}</p></article><aside class="paper list-panel"><div class="overline">${chosen.length} ${TEXT.selection.toLowerCase()}</div><h2>${esc(TEXT.essential)}</h2>${chosen.map((c,i)=>`<a class="list-food" href="#food-${i}">${image(c.f.id)}<span><strong>${esc(c.f.nom.split(' (')[0])}</strong><small>${esc(c.f.portion_type)}</small></span><em>${String(i+1).padStart(2,'0')}</em></a>`).join('')}<a class="primary" href="#details" style="margin-top:20px">${TEXT.viewDetail} ↗</a></aside></div><div class="signals"><article><div class="overline">${TEXT.season}</div><b>${seasonal}/${chosen.length}</b><p>${TEXT.availableMonth}</p></article><article><div class="overline">${TEXT.proof}</div><b>${proof}</b><p>${TEXT.strongestLevel}</p></article><article><div class="overline">${TEXT.selection}</div><b>${chosen.length}</b><p>${TEXT.selectionRules}</p></article></div>`}${mode==='normal'?filterUI():`<div class="links">${button(TEXT.answer,'questions','text-button')}</div>`}<div class="page-links">${TEXT.sections.map(([id,t])=>`<a href="#${id}">${t} ↗</a>`).join('')}</div><section id="details"><h2>${TEXT.details}</h2>${chosen.map((c,i)=>detailsFor(c,i,ex)).join('')}</section><div id="continuation"></div></main>`;renderSections(z);wireResult();saveMemory()}
function safeText(text){return !/superaliment|détox|anti[-‑ ]âge|booste|\bIA\b/i.test(String(text||''))}
function trendsMarkup(){const allowed=Core.get().trends.filter(t=>[t.accroche,t.verdict_texte,t.ce_quon_peut_faire,t.prudence,...(t.etudes||[]).map(e=>e.ref)].every(safeText));const labels={prouve:'Prouvé',plausible:'Plausible',pas_demontre:'Pas démontré',deconseille:'Déconseillé'};return `<div class="overline">Collagène, matcha, vinaigre de cidre…</div><h2>${TEXT.trendsTitle}</h2><p>Ce que disent vraiment les études sur les tendances du moment. Sans parti pris, sources à l’appui.</p>${allowed.slice(0,trendCount).map(t=>`<article class="rit"><div><div class="overline">${esc(labels[t.verdict])}</div><h3>${esc(t.accroche)}</h3><p>${esc(t.verdict_texte)}</p>${t.ce_quon_peut_faire?`<p>${esc(t.ce_quon_peut_faire)}</p>`:''}${t.prudence?`<p class="prec">${esc(t.prudence)}</p>`:''}<details><summary>${TEXT.studiesLabel} (${t.etudes?.length||0})</summary>${(t.etudes||[]).map(e=>`<a href="${esc(e.lien)}" target="_blank" rel="noopener">${esc(e.ref)} ↗</a>`).join('')}</details></div></article>`).join('')}${allowed.length>trendCount?button(TEXT.moreTrendsPrefix+' '+(allowed.length-trendCount)+' '+TEXT.moreTrendsSuffix,'moreTrends','secondary'):''}`}
function memoryMarkup(){if(mode!=='normal')return `<h2>${TEXT.responses}</h2><p>${TEXT.prudentLead}</p>${button(TEXT.answer,'questions')}`;return `<div class="memory"><h2>${TEXT.responses}</h2><p>${esc(Core.phrase(s))}</p>${button(TEXT.changeResponses,'questions','secondary')}<label><input id="keep" type="checkbox" ${keep?'checked':''}><span>${TEXT.keep}<br><small class="fine">${TEXT.keepHelp}</small></span></label>${keep&&saved?`<p class="fine">${TEXT.keepUntil} ${esc(new Date(saved.expire+'T12:00:00').toLocaleDateString('fr-FR'))}. ${button(TEXT.eraseNow,'eraseNow','text-button')}</p>`:''}</div>`}
function renderSections(z){Core.recipeTab(recipeTab,recipeCount);const target=document.getElementById('continuation');target.innerHTML=`<section class="section" id="combos"><div id="comboContent">${Core.combos(z.ind,z.chosen)}</div></section><section class="section" id="recipes">${Core.recipes(z.chosen,z.ex.x)}</section><section class="section" id="near"><div id="vy-as-geo"></div></section><section class="section" id="rhythm">${Core.rhythm()}</section><section class="section" id="trends">${trendsMarkup()}</section><section class="section" id="responses">${memoryMarkup()}</section><p class="fine">${TEXT.cautionFooter}</p><details><summary>${TEXT.warningLink}</summary><p class="fine">${esc(TEXT.warningFull)}</p></details><p class="fine">${TEXT.info}</p>`;Core.near(z.chosen);const nearButton=document.getElementById('vy-as-geo-go');if(nearButton){const original=nearButton.onclick;nearButton.onclick=function(){if(stream)stopCamera();original.call(this)}};adaptNativeElements();Core.catalogue().then(()=>{const el=document.getElementById('comboContent');if(!el)return;el.innerHTML=Core.combos(z.ind,z.chosen);el.querySelectorAll('img').forEach(img=>{/* en ligne, /scan/ est deja le bon chemin */0});el.querySelectorAll('.prod').forEach(a=>{if(!safeText(a.textContent))a.remove()});decorateCombos(el);adaptNativeElements(el)});}
function decorateCombos(el){const title=el.querySelector('h2');if(title)title.innerHTML='Un aliment,<br>un soin.';el.querySelectorAll('.rit').forEach(row=>{const title=row.querySelector('h3')?.textContent.split(' + ')[0];const f=Core.get().data.find(f=>f.nom.split(' (')[0]===title);if(!f)return;const area=document.createElement('div');area.className='pair-visual';area.innerHTML=image(f.id);const product=row.querySelector('.prod img');if(product){const copy=product.cloneNode();copy.alt='';area.append(copy)}const desc=row.querySelector('p');desc?.before(area);row.querySelector('.alleg')?.remove();});}
function adaptNativeElements(target=app){target.querySelectorAll('span.puce').forEach(el=>{let b=document.createElement('button');b.type='button';b.className=el.className;b.innerHTML=el.innerHTML;for(const attr of el.attributes)if(attr.name.startsWith('data-'))b.setAttribute(attr.name,attr.value);b.setAttribute('aria-pressed',String(el.classList.contains('on')));el.replaceWith(b)});target.querySelectorAll('img').forEach(img=>{/* en ligne, /scan/ est deja le bon chemin */0})}
function wireResult(){document.getElementById('budget')?.addEventListener('change',e=>{prefs.budget=e.target.value||null;refreshResult()});document.getElementById('keep')?.addEventListener('change',e=>{if(e.target.checked){keep=true;saveMemory(true);refreshResult()}else eraseMemory(false)});app.querySelectorAll('[data-onglet]').forEach(el=>el.onclick=()=>{recipeTab=el.dataset.onglet;recipeCount=3;refreshResult()});document.getElementById('vy-as-plusrec')?.addEventListener('click',()=>{recipeCount+=6;refreshResult()});app.querySelectorAll('[data-ry]').forEach(el=>el.onclick=()=>{let k=el.dataset.ry,v=el.dataset.v;ry[k==='d'?'q9d':k]=k==='d'?!ry.q9d:ry[k]===v?null:v;bindCore();saveMemory();refreshResult()})}
function refreshResult(){const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'})}
function suiteView(){const z=prepareSelection();if(!z){missingScan();return}app.innerHTML=`<main class="results"><div class="result-head"><div><div class="overline">${TEXT.afterPlate}${demo?' · '+TEXT.demonstration:''}</div><h1>${esc(TEXT.suite)}</h1></div><p>${TEXT.suiteLead}</p></div><div class="page-links">${TEXT.sections.map(([id,t])=>`<a href="#${id}">${t} ↗</a>`).join('')}</div><div id="continuation"></div></main>`;renderSections(z);wireResult()}

function galleryView(){['grenade','kiwi','orange','avocat','fruit_passion','poire','citron','mangue','fraise','peche','chou_rouge','radis','clementine','tomate','melon','abricot_sec','graines_lin','myrtille','huile_olive','poivron_rouge'].forEach(id=>shownPhotos.add(id));app.innerHTML=`<main class="gallery"><div class="overline">Études · Parcours Aliment</div><h1>${esc(TEXT.galleryTitle)}</h1><p class="intro">${TEXT.galleryLead}</p><div class="frame-actions">${button(TEXT.start,'questions')}<a class="secondary" href="NOTES.md">${TEXT.notes}</a></div>${gallerySteps.map(([num,title,desc,cards])=>`<section class="step"><div class="overline">${num} / 05</div><h2>${title}</h2><p>${desc}</p><div class="cards">${cards.map(([route,t])=>`<a class="card" href="${routes[route]}" data-go="${route}"><img loading="lazy" src="captures/${route}-desktop.png" alt="${TEXT.previewPrefix} : ${esc(t)}"><h3>${t}</h3><p>${TEXT.openScreen} ↗</p></a>`).join('')}</div></section>`).join('')}</main>`}
function render(){shownPhotos.clear();bindCore();document.title='vyvre — '+(window.SCREEN_TITLE||TEXT.food);if(['questions','allergies','besoin','types','preference','consent'].includes(pageName)&&mode!=='normal')mode=null;if(pageName==='questions')questions();else if(pageName==='allergies')allergies();else if(pageName==='besoin')besoin();else if(pageName==='types')envies();else if(pageName==='preference')preference();else if(pageName==='consent')agreement();else if(pageName==='return')returnView();else if(pageName==='scan')scanView();else if(pageName==='composition')composition();else if(pageName==='wheel')composition(true);else if(pageName==='result')resultView();else if(pageName==='resultSolo')resultView(true);else if(pageName==='suite')suiteView();else galleryView();document.getElementById('disclaimer').innerHTML=shortDisclaimer();}
app.addEventListener('click',async e=>{const goLink=e.target.closest('[data-go]');if(goLink){e.preventDefault();go(goLink.dataset.go);return}const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.case){const key=b.dataset.case;s.rien=false;if(['allergie','regime'].includes(key)){s._cases[key]=!s._cases[key];if(key==='allergie'&&!s._cases[key]){s.allergies=[];s.autres_aliments=[];s._autre=false}if(key==='regime'&&!s._cases[key])s.regime=null}else s[key]=!s[key];render();if(validQuestion())auto('questionNext',2000);else clearTimeout(autoT);return}
 if(b.dataset.regime){s.regime=s.regime===b.dataset.regime?null:b.dataset.regime;render();if(validQuestion())auto('questionNext',1600);return}
 if(b.dataset.allergen){const id=b.dataset.allergen;if(id==='autre'){s._autre=!s._autre;if(!s._autre)s.autres_aliments=[]}else toggle(s.allergies,id);render();if(id!=='autre'&&Core.valid(s))auto('allergyNext',2200);else clearTimeout(autoT);return}
 if(b.dataset.other){toggle(s.autres_aliments,b.dataset.other);render();return}
 if(b.hasAttribute('data-usage')){prefs.usage=b.dataset.usage||null;render();auto('consent',b.dataset.usage?1700:500);return}
 if(b.dataset.bio){prefs.bio=!prefs.bio;render();auto('consent',1700);return}
 if(b.dataset.besoin){prefs.besoins=prefs.besoins||[];toggle(prefs.besoins,b.dataset.besoin);bindCore();render();if(prefs.besoins.length)auto('types',1800);else clearTimeout(autoT);return}
 if(b.dataset.type){prefs.types=prefs.types||[];toggle(prefs.types,b.dataset.type);bindCore();render();if(prefs.types.length)auto('preference',1800);else clearTimeout(autoT);return}
 if(b.dataset.filter){const k=b.dataset.filter;prefs[k]=!prefs[k];refreshResult();return}
 if(b.dataset.cuisine){const id=b.dataset.cuisine;if(prefs.cuisines.includes(id)||prefs.cuisines.length<3)toggle(prefs.cuisines,id);refreshResult();return}
 if(b.dataset.remove){removed.push(b.dataset.remove);bindCore();saveMemory();refreshResult();return}
 if(b.dataset.focus){foodFocus=Number(b.dataset.focus);refreshResult();return}
 const a=b.dataset.action;if(!a)return;
 clearTimeout(autoT);
 if(a==='nothing'){s={rien:true,_cases:{},allergies:[],autres_aliments:[],regime:null};go('besoin')}
 else if(a==='besoinAny'){prefs.besoins=[];bindCore();go('types')}
 else if(a==='typesAny'){prefs.types=[];bindCore();go('preference')}
 else if(a==='questionNext'){if(validQuestion())go(s._cases.allergie?'allergies':'besoin')}
 else if(a==='allergyNext'){if(Core.valid(s))go('besoin')}
 else if(a==='accept'){if(Core.valid(s)){mode='normal';bindCore();if(keep)saveMemory(true);syncScores(null,false);autoCam=false;go('scan')}}
 else if(a==='refuse'||a==='minor'){s={_cases:{},allergies:[],autres_aliments:[]};mode=a==='minor'?'mineur':'prudent';keep=false;ry={q9s:null,q9d:false,q10p:null};bindCore();syncScores(null,false);autoCam=false;go('scan')}
 else if(a==='camera')await camera();else if(a==='read')await readVideo();
 else if(a==='demoScan'){try{await runImage('portrait-demo.jpg',true)}catch{}}
 else if(a==='demoDestination'){const target=pageName;if(!mode)mode='prudent';try{await demoForDestination(target)}catch{}}
 else if(a==='lastScan'){const last=hasStoredScan();if(last){syncScores(last,false);render()}}
 else if(a==='resetRemoved'){removed=[];refreshResult()}
 else if(a==='moreTrends'){trendCount=99;refreshResult()}
 else if(a==='eraseNow'||a==='eraseReturn')eraseMemory(a==='eraseReturn');
 else if(a==='another'){keep=false;s={_cases:{},allergies:[],autres_aliments:[]};mode=null;go('questions')}
 else if(a==='same'||a==='modify'){if(saved){s=JSON.parse(JSON.stringify(saved.sante));s._cases={allergie:!!(s.allergies.length||s.autres_aliments.length),regime:!!s.regime};mode='normal';keep=true;ry=saved.rythme||ry;removed=saved.paspour||[];go(a==='same'?(scores?'composition':'scan'):'questions')}}
 else if(routes[a])go(a);
});
function toggle(array,value){const i=array.indexOf(value);if(i>=0)array.splice(i,1);else array.push(value)}
async function creditsDialog(){let dialog=document.getElementById('photoCredits');if(!dialog){dialog=document.createElement('dialog');dialog.id='photoCredits';dialog.setAttribute('aria-labelledby','creditsTitle');document.body.append(dialog)}const names=Core.get().credits;const used=Array.from(shownPhotos).filter(id=>names[id]);dialog.innerHTML=`${button(TEXT.close,'closeCredits','secondary close')}<h2 id="creditsTitle">${TEXT.credits}</h2><ul>${used.map(id=>{const c=names[id];return `<li><strong>${esc(id.replace(/_/g,' '))}</strong> · ${esc(c.titre)}<br>${esc(c.auteur)} · <a href="${esc(c.licence_url)}" target="_blank" rel="noopener">${esc(c.licence)}</a> · <a href="${esc(c.source_url)}" target="_blank" rel="noopener">Source</a><br>PNG détouré fourni par vyvre, même licence ; aucune retouche supplémentaire.</li>`}).join('')}</ul>`;dialog.querySelector('button').onclick=()=>dialog.close();dialog.showModal()}
document.getElementById('creditButton').onclick=creditsDialog;document.getElementById('navGallery').onclick=e=>{e.preventDefault();go('gallery')};
window.Parcours={go,getState:()=>({page:pageName,mode,demo,keep,scores,health:s,prefs,removed,selected:mode&&Core.indices()?Core.choose(Core.indices()).map(c=>c.f.id):[]}),ready:()=>loaded};
(async()=>{globalChrome();app.innerHTML=`<main class="busy"><h1>${TEXT.loading}</h1></main>`;try{await Core.load();saved=loadMemory();if(saved){try{const p=JSON.parse(localStorage.getItem(PREFS)||'null');if(p&&[null,'quotidien','decouverte','tendance'].includes(p.usage)&&[null,'serre','moyen'].includes(p.budget)&&Array.isArray(p.cuisines)){prefs={saison:typeof p.saison==='boolean'?p.saison:true,usage:p.usage,cuisines:p.cuisines.filter(id=>Core.cuisines.some(c=>c[0]===id)).slice(0,3),budget:p.budget,bio:!!p.bio,cuis:false}}}catch{}}const real=hasStoredScan();if(real)syncScores(real,false);loaded=true;if(pageName==='questions'&&saved)pageName='return';render()}catch(e){app.innerHTML=`<main class="busy"><h1>${TEXT.openLocal}</h1><p>${TEXT.unavailable}</p></main>`;console.error(e)}})();
